import React from 'react';

/**
 * Raw inline SVG artwork that Material Icons does not provide — chiefly brand marks.
 *
 * Each export is the bare `<svg>` with no sizing or styling of its own; callers pass the SVG props
 * they need (`height`, `className`, `aria-label`, …). Add further icons to this file rather than
 * creating one module per glyph.
 */

/** The flag of India (Tiranga), drawn to the official 3:2 ratio with a 24-spoke Ashoka Chakra. */
